-- Deities and Demigods divine framework, normalized for the D&D 3.5 ruleset.
-- Primary source: Deities and Demigods (2002), chapters 1-2 and appendix 2.
-- Revision source: the official D&D v.3.5 Accessory Update appended to the supplied PDF.
-- Mechanical prose is summarized; source pages remain authoritative.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES
  ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0','Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL),
  ('dd-3.5-update','deities-and-demigods-3-5-update','Deities and Demigods - D&D v.3.5 Accessory Update','DD 3.5 Update','Wizards of the Coast','dnd','3.5','Official revision notes that update Deities and Demigods to the revised 3.5 core rules. These rows supersede conflicting 3.0 mechanics from the book.',NULL,1,0,NULL);

WITH desired(slug,name,page,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,summary,tags,mechanics) AS (VALUES
  ('dd-divine-rank','Divine Rank','25-26','divinity','subsystem',0,1,NULL,NULL,
   'Divine rank measures godly power. Mortals have no divine rank; rank 0 entities are quasi-deities, ranks 1-5 demigods, 6-10 lesser deities, 11-15 intermediate deities, 16-20 greater deities, and rank 21+ overdeities.',
   '["deity","divine-rank","divinity"]',
   '{"bands":[{"min":0,"max":0,"name":"quasi-deity","grantsSpells":false},{"min":1,"max":5,"name":"demigod","grantsSpells":true},{"min":6,"max":10,"name":"lesser deity","grantsSpells":true},{"min":11,"max":15,"name":"intermediate deity","grantsSpells":true},{"min":16,"max":20,"name":"greater deity","grantsSpells":true},{"min":21,"name":"overdeity","grantsSpells":false}],"mortal_has_rank":false}'),
  ('dd-salient-divine-ability-allocation','Salient Divine Ability Allocation','31-33','divinity','rule',0,1,'dd-divine-rank',NULL,
   'A deity of rank 1 or higher gains one salient divine ability per divine rank, plus additional abilities based on divine status. Rank 0 quasi-deities gain none.',
   '["deity","divine-rank","salient-divine-ability"]',
   '{"per_divine_rank":1,"rank_0":0,"status_bonus":{"demigod":1,"lesser":2,"intermediate":3,"greater":5},"minimum_rank":1}'),
  ('dd-salient-divine-ability-use','Using Salient Divine Abilities','32-33','divinity','rule',0,1,'dd-salient-divine-ability-allocation',NULL,
   'Unless an ability says otherwise, activating a salient divine ability is a standard action, does not provoke an attack of opportunity, functions in antimagic, and is not subject to spell resistance.',
   '["deity","salient-divine-ability","antimagic","spell-resistance"]',
   '{"default_action":"standard","provokes_attack_of_opportunity":false,"functions_in_antimagic":true,"subject_to_spell_resistance":false}'),
  ('dd-divine-senses','Divine Senses','26-27','divinity','subsystem',0,1,'dd-divine-rank',NULL,
   'Deities possess extraordinarily acute senses whose normal range scales with divine rank and can extend their perception through worshipers, holy sites, objects, and locations tied to their names or titles.',
   '["deity","senses","remote-sensing"]',
   '{"normal_range_miles":"divine rank","remote_sensing":true,"remote_locations_scale_by_rank":true}'),
  ('dd-portfolio-sense','Portfolio Sense','27','divinity','subsystem',0,1,'dd-divine-rank',NULL,
   'A deity can sense events related to its portfolio, with the breadth, distance, history, and advance warning improving as divine rank increases.',
   '["deity","portfolio","senses"]','{"scales_with_divine_rank":true}'),
  ('dd-automatic-actions','Automatic Actions','27','divinity','subsystem',0,1,'dd-divine-rank',NULL,
   'Deities can perform selected skill or ability tasks as free actions when the task DC is within the threshold allowed by their divine rank.',
   '["deity","skills","automatic-actions"]','{"action":"free","scales_with_divine_rank":true}'),
  ('dd-create-magic-items','Divine Item Creation','27','divinity','rule',0,1,'dd-divine-rank',NULL,
   'Deities can create magic items using their divine capabilities, subject to the item-creation requirements and divine rules described in the source.',
   '["deity","crafting","magic-items"]','{}'),
  ('dd-divine-aura','Divine Aura','28','divinity','subsystem',0,1,'dd-divine-rank',NULL,
   'A deity of rank 1 or higher projects a supernatural aura whose radius scales with divine rank and whose effect can be selected from dread, resolve, or love/admiration style responses.',
   '["deity","aura","fear","morale"]','{"minimum_rank":1,"radius_scales_with_rank":true,"effect_choices":["daze/dread","resolve","love/admiration"]}'),
  ('dd-divine-immunities','Divine Immunities','26-29','divinity','subsystem',0,1,'dd-divine-rank',NULL,
   'Divine beings gain broad immunities and resistances according to divine rank. The 3.5 update retains the divine immunity framework while revising related damage reduction and resistance values.',
   '["deity","immunity","resistance"]','{"minimum_rank":0}'),
  ('dd-divine-damage-reduction','Divine Damage Reduction','26-29','divinity','table',0,1,'dd-divine-rank',NULL,
   'In the 3.5 update, deity damage reduction is based on divine-rank band and is bypassed by epic attacks, with higher divine status granting greater reduction.',
   '["deity","damage-reduction","3.5-update"]','{"rank_bands":[{"min":0,"max":0,"dr":"10/epic"},{"min":1,"max":5,"dr":"15/epic"},{"min":6,"max":10,"dr":"20/epic"},{"min":11,"max":15,"dr":"25/epic"},{"min":16,"max":20,"dr":"30/epic"}]}'),
  ('dd-divine-fire-resistance','Divine Fire Resistance','26-29','divinity','rule',0,1,'dd-divine-immunities',NULL,
   'The 3.5 update sets a deity''s fire resistance to 5 plus divine rank.',
   '["deity","fire","resistance","3.5-update"]','{"fire_resistance":"5 + divine rank"}'),
  ('dd-divine-spell-resistance','Divine Spell Resistance','26-29','divinity','rule',0,1,'dd-divine-immunities',NULL,
   'Deities possess spell resistance determined by their divine statistics; rank 0 quasi-deities use the revised quasi-deity trait package where applicable.',
   '["deity","spell-resistance"]','{}'),
  ('dd-divine-immortality','Divine Immortality','29','divinity','rule',0,1,'dd-divine-rank',NULL,
   'Deities are immortal in the sense defined by the divine rules and do not age or die from ordinary mortal causes, though campaign cosmology can define methods of deicide or loss of divinity.',
   '["deity","immortality","deicide"]','{}'),
  ('dd-divine-spell-like-abilities','Divine Spell-Like Abilities','28-30','divinity','subsystem',0,1,'dd-divine-rank',NULL,
   'A deity can use domain spells associated with its domains as spell-like abilities, with caster level and save DC determined by the divine rules.',
   '["deity","domains","spell-like-abilities"]','{"domain_based":true,"scales_with_divine_rank":true}'),
  ('dd-divine-character-levels','Deities and Character Levels','25-31','divinity','rule',0,1,'dd-divine-rank',NULL,
   'Divine rank is separate from Hit Dice and class levels. Deities still use ordinary character and monster statistics, with divine traits layered on top.',
   '["deity","character-level","hit-dice"]','{"divine_rank_separate_from_character_level":true}'),
  ('dd-divine-3.5-class-updates','Deity Class-Level 3.5 Updates','update 3-5','divinity','guidance',0,1,'dd-divine-character-levels',NULL,
   'When using deity stat blocks under 3.5, apply the revised class features for barbarian, bard, druid, monk, paladin, ranger, rogue, wizard, and other affected classes rather than their 3.0 versions.',
   '["deity","3.5-update","class-features"]','{"source":"official 3.5 accessory update","use_revised_core_class_features":true}'),
  ('dd-divine-alignment-subtypes','Divine Alignment Subtypes','update 3-5','divinity','rule',0,1,'dd-divine-character-levels',NULL,
   'Under the 3.5 update, outsider deities gain all alignment subtypes corresponding to their alignment, and their natural attacks and wielded weapons count as aligned accordingly for bypassing damage reduction.',
   '["deity","outsider","alignment","damage-reduction","3.5-update"]','{"gain_matching_alignment_subtypes":true,"natural_and_wielded_attacks_count_as_aligned":true}'),
  ('dd-quasi-deity-traits-3.5','Quasi-Deity Traits (3.5)','update 6','divinity','rule',0,1,'dd-divine-rank',NULL,
   'The official 3.5 update defines the rank-0 quasi-deity package: immunity to transmutation, energy drain, ability drain, ability damage and mind-affecting effects; damage reduction 10/epic; fire resistance 5; spell resistance 32; and immortality.',
   '["deity","quasi-deity","rank-0","3.5-update"]','{"rank":0,"immunities":["transmutation","energy drain","ability drain","ability damage","mind-affecting effects"],"damage_reduction":"10/epic","fire_resistance":5,"spell_resistance":32,"immortal":true}'),
  ('dd-loose-pantheon','Loose Pantheon','5-6','religion','guidance',1,1,NULL,NULL,
   'A loose pantheon consists of multiple distinct deities whose followers generally choose individual patrons while acknowledging the other gods.',
   '["religion","pantheon","cleric"]','{"cleric_domain_source":"patron deity"}'),
  ('dd-tight-pantheon','Tight Pantheon','6-7','religion','subsystem',1,0,NULL,NULL,
   'A tight pantheon operates as a single religion. Clerics may serve an individual deity or the pantheon as a whole and, when serving the whole, choose domains from the pantheon''s non-aberrant deities subject to alignment-domain restrictions.',
   '["religion","pantheon","cleric","variant"]','{"pantheon_clerics":true,"exclude_aberrant_deity_domains":true,"alignment_domain_restrictions":true}'),
  ('dd-mystery-cult','Mystery Cult','7','religion','guidance',1,0,NULL,NULL,
   'A mystery cult is an initiatory religion centered on an intensely personal relationship with one deity or a small related group, usually within a broader pantheon.',
   '["religion","mystery-cult","initiation"]','{}'),
  ('dd-monotheism','Monotheism','7-8','religion','subsystem',1,0,NULL,NULL,
   'A monotheistic campaign centers worship on one deity. Domain availability, cleric alignment, rival supernatural powers, and whether divine ascension is possible are campaign decisions.',
   '["religion","monotheism","cleric","variant"]','{"campaign_model":"monotheism"}'),
  ('dd-dualism','Dualism','8-9','religion','subsystem',1,0,NULL,NULL,
   'A dualistic religion organizes the cosmos around two opposed divine powers or principles, often restricting cleric alignment and dividing domains between the two sides.',
   '["religion","dualism","cleric","variant"]','{"campaign_model":"dualism"}'),
  ('dd-animism','Animism','9','religion','subsystem',1,0,NULL,NULL,
   'Animism treats the world as filled with spirits. Clerics generally serve the spirit-world as a whole and can select domains representing patron spirits, subject to alignment restrictions.',
   '["religion","animism","cleric","variant"]','{"campaign_model":"animism"}'),
  ('dd-forces-and-philosophies','Forces and Philosophies','9','religion','subsystem',1,0,NULL,NULL,
   'Divine spellcasting can be grounded in impersonal forces or strongly held philosophies rather than a named deity; clerics use domain and alignment restrictions defined by the chosen force or philosophy.',
   '["religion","philosophy","cleric","variant"]','{"patron_deity_required":false}'),
  ('dd-limited-divine-power','Limited or Infinite Divine Power','9-10','divinity','guidance',1,0,NULL,NULL,
   'A campaign may define divine power as finite, requiring ranks to be surrendered, stolen, or freed before another being can gain them, or as effectively unlimited.',
   '["divinity","campaign-design","divine-rank"]','{"models":["finite","unlimited"]}'),
  ('dd-innate-divinity','Innate Divinity','10','divinity','guidance',1,0,NULL,NULL,
   'Under an innate-divinity model, gods are born divine and mortals normally cannot earn divinity unless the campaign establishes a separate method of imparting it.',
   '["divinity","ascension","campaign-design"]','{"ascension_model":"innate"}'),
  ('dd-earned-divinity','Earned Divinity','10-11','divinity','guidance',1,0,NULL,NULL,
   'Under an earned-divinity model, mortals who satisfy repeatable campaign-defined requirements can attain divine status independently of a god choosing them.',
   '["divinity","ascension","campaign-design"]','{"ascension_model":"earned"}'),
  ('dd-stolen-divinity','Stolen Divinity','11','divinity','guidance',1,0,NULL,NULL,
   'Under a stolen-divinity model, divine power has a transferable form that can be taken from an existing deity, creating a new god while diminishing or dethroning the victim.',
   '["divinity","ascension","deicide","campaign-design"]','{"ascension_model":"stolen"}'),
  ('dd-imparted-divinity','Imparted Divinity','11-12','divinity','guidance',1,0,NULL,NULL,
   'Under an imparted-divinity model, an existing deity or divine authority deliberately grants divine rank to a worthy candidate.',
   '["divinity","ascension","campaign-design"]','{"ascension_model":"imparted"}'),
  ('dd-surrendered-divinity','Surrendered Divinity','12','divinity','guidance',1,0,NULL,NULL,
   'A campaign can allow deities to surrender some or all divine status temporarily or permanently, including transferring power to successors.',
   '["divinity","ascension","campaign-design"]','{"ascension_model":"surrendered"}'),
  ('dd-dependent-independent-deities','Dependent and Independent Deities','12-13','divinity','guidance',1,0,NULL,NULL,
   'A deity may derive power from worship, sacrifice, portfolio conditions, or no external source at all; this choice shapes divine politics and the consequences of losing worshipers.',
   '["divinity","worship","campaign-design"]','{}'),
  ('dd-active-distant-deities','Active and Distant Deities','17-18','divinity','guidance',1,0,NULL,NULL,
   'Campaigns can choose how directly deities intervene in mortal affairs, from frequent personal involvement to remote or constrained divine action.',
   '["divinity","campaign-design","intervention"]','{}'),
  ('dd-deicide','Deicide','18-19','divinity','subsystem',1,0,NULL,NULL,
   'The campaign decides whether gods can die, what is required to kill them, and what happens to divine rank, portfolios, realms, worshipers, and spells afterward.',
   '["divinity","deicide","campaign-design"]','{}'),
  ('dd-building-pantheon','Building a Pantheon','19-20','religion','procedure',1,0,NULL,NULL,
   'Pantheon construction assigns deities, alignments, portfolios, domains, relationships, divine power assumptions, and cosmological roles according to the chosen religious model.',
   '["religion","pantheon","worldbuilding"]','{}'),
  ('dd-divine-realms','Cosmology and Divine Realms','20-24','divinity','subsystem',1,0,NULL,NULL,
   'Deities can possess divine realms whose characteristics and scope reflect divine rank, portfolio, plane, and campaign cosmology.',
   '["deity","divine-realm","planes","cosmology"]','{"scales_with_divine_rank":true}'),
  ('dd-proxies','Divine Proxies','54-55','divinity','subsystem',0,1,NULL,NULL,
   'A deity can invest a mortal or other creature as a proxy, granting a portion of divine power while the proxy serves as an empowered agent.',
   '["deity","proxy","divine-minion"]','{}'),
  ('dd-petitioners','Petitioners','55-56','divinity','subsystem',0,1,NULL,NULL,
   'Petitioners are the transformed souls of the dead on the Outer Planes, with traits based on their destination and patron; they generally lose much of their mortal identity and progression.',
   '["deity","petitioner","afterlife","divine-minion"]','{}'),
  ('dd-divine-ascension','Divine Ascension','218-223','divinity','subsystem',1,0,NULL,NULL,
   'Divine ascension is a campaign-level progression that can transform sufficiently accomplished mortals into rank-0 or higher divine beings when the cosmology permits it. The source presents planning guidance, finite/unlimited divinity, and innate, earned, stolen, or granted routes.',
   '["divinity","ascension","epic","player-character"]','{"typical_candidate_level":20,"lower_than_15_rare":true,"possible_start_rank":0,"requires_campaign_permission":true}'),
  ('dd-3.5-domain-spell-revisions','Deities and Demigods Domain Spell Revisions','update 6','domains','table',0,1,NULL,NULL,
   'The official 3.5 update replaces renamed or revised core-domain spells and modifies several Deities and Demigods domain lists. Revised 3.5 spell versions take precedence.',
   '["domains","spells","3.5-update","precedence"]','{"use_revised_core_spell_versions":true,"changes":{"Animal":["summon nature''s ally IV replaces repel vermin","summon nature''s ally VIII replaces creeping doom"],"Destruction":["mass inflict light wounds replaces circle of doom"],"Fire":["resist energy replaces resist elements"],"Healing":["mass cure light wounds replaces healing circle","mass cure critical wounds replaces true resurrection"],"Luck":["protection from energy replaces protection from elements","moment of prescience replaces holy aura"],"Magic":["Nystul''s magic aura replaces Nystul''s undetectable aura"],"Plant":["animate plants replaces changestaff"],"Protection":["protection from energy replaces protection from elements"],"Strength":["enlarge person replaces endure elements"],"Travel":["longstrider replaces expeditious retreat","greater teleport replaces teleport without error"],"Trickery":["disguise self replaces change self"],"Charm":["heroism replaces emotion"],"Community":["status replaces shield other","greater status replaces old status slot","sympathy replaces mass heal at 8th","mass heal replaces miracle at 9th"],"Liberation":["freedom replaces omitted unbinding"],"Madness":["use revised Player''s Handbook rage"],"Repose":["use revised Player''s Handbook undeath to death"],"Rune":["symbol of death replaces symbol"],"Weather":["call lightning storm replaces ice storm at 5th"]}}')
)
INSERT INTO dnd35_rules
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,category,kind,is_variant,default_enabled,parent_slug,supersedes_slug,tags,mechanics)
SELECT 'dd-rule-'||d.slug,
       CASE WHEN d.slug IN ('dd-divine-damage-reduction','dd-divine-fire-resistance','dd-divine-3.5-class-updates','dd-divine-alignment-subtypes','dd-quasi-deity-traits-3.5','dd-3.5-domain-spell-revisions') THEN 'dd-3.5-update' ELSE 'dd-3.0' END,
       d.page,d.slug,d.name,d.summary,d.summary,0,NULL,1,d.category,d.kind,d.is_variant,d.default_enabled,d.parent_slug,d.supersedes_slug,d.tags,d.mechanics
FROM desired d
WHERE NOT EXISTS (SELECT 1 FROM dnd35_rules r WHERE r.slug=d.slug AND r.owner_user_id IS NULL);
